def set_checked(obj,desired):
    schema=json.loads(execute_tool("editor_toolset.toolsets.object.ObjectTools.list_properties",json.dumps({"instance":obj}))["returnValue"])
    values={}
    for wanted,value in desired.items():
        key=next((k for k in schema if k.lower().replace("_","")==wanted.lower().replace("_","")),None)
        assert key,(wanted,list(schema))
        values[key]=value
    execute_tool("editor_toolset.toolsets.object.ObjectTools.get_properties",json.dumps({"instance":obj,"properties":list(values)}))
    assert execute_tool("editor_toolset.toolsets.object.ObjectTools.set_properties",json.dumps({"instance":obj,"values":json.dumps(values)}))["returnValue"]
